    if(sl){const d=this._defs()[+sl.dataset.sl];if(!d)return;this._dr={el:sl,d,r:sl.getBoundingClientRect(),id:e.pointerId,x:e.clientX,moved:false,v:null};try{this.setPointerCapture(e.pointerId)}catch(_){}return}
