  _upd(dr,x){const d=dr.d,f=Math.max(0,Math.min(1,(x-dr.r.left)/(dr.r.width||1)));let v=d.min+f*(d.max-d.min);v=Math.max(d.min,Math.min(d.max,Math.round(v/d.step)*d.step));dr.v=+v.toFixed(4);
    dr.el.style.setProperty('--f',((v-d.min)/((d.max-d.min)||1)).toFixed(4));dr.el.classList.remove('z');const s=this.shadowRoot.querySelector('[data-val]');if(s)s.textContent=d.txt(v)}
