/* ---------- Mond (berechnet, ohne Integration) ---------- */
function moonAt(t){const syn=29.530588853,ref=Date.UTC(2000,0,6,18,14),ph=(((t-ref)/864e5)%syn+syn)%syn/syn;return{ph,ill:(1-Math.cos(2*Math.PI*ph))/2,toFull:((.5-ph+1)%1)*syn,toNew:((1-ph)%1)*syn}}
