function feedDate(v){if(v==null||v==='')return null;const s=String(v).trim(),now=Date.now();let d=null;
  const hasY=/\b(19|20)\d\d\b/.test(s)||/^\d{4}-\d\d/.test(s);
  if(hasY){d=new Date(s);if(isNaN(d))d=null}
  if(!d){const m=s.match(/\b([a-zäöü]{3})[a-zäöü]*\.?\s+(\d{1,2})\b(?:,?\s+((?:19|20)\d\d))?(?:,?\s+(\d{1,2}):(\d{2})(?::\d{2})?\s*(am|pm)?)?/i)||null;
    const m2=m?null:s.match(/\b(\d{1,2})\.?\s+([a-zäöü]{3})[a-zäöü]*\.?(?:\s+((?:19|20)\d\d))?(?:,?\s+(\d{1,2}):(\d{2}))?/i);
    let mo,da,yr,hh=12,mi=0,ap;
    if(m){mo=MON[m[1].toLowerCase()];da=+m[2];yr=m[3]?+m[3]:null;if(m[4]!=null){hh=+m[4];mi=+m[5];ap=m[6]}}
    else if(m2){mo=MON[m2[2].toLowerCase()];da=+m2[1];yr=m2[3]?+m2[3]:null;if(m2[4]!=null){hh=+m2[4];mi=+m2[5]}}
    if(mo==null||!da)return null;if(ap){ap=ap.toLowerCase();if(ap==='pm'&&hh<12)hh+=12;if(ap==='am'&&hh===12)hh=0}
    const y0=new Date().getFullYear();d=new Date(yr||y0,mo,da,hh,mi);if(!yr&&d-now>2*864e5)d=new Date(y0-1,mo,da,hh,mi)}
  if(!d||isNaN(d)||d-now>2*864e5||now-d>3650*864e5)return null;return d}
const okLink=u=>typeof u==='string'&&/^https?:\/\//i.test(u)?u:'';
